import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { 
  Bell, 
  Search, 
  Menu, 
  User, 
  Settings, 
  LogOut, 
  ChevronRight,
  Home,
  MessageSquare,
  ShoppingCart,
  Users,
  BarChart,
  FileText,
  Calendar,
  Database,
  Shield,
  HelpCircle,
  X,
  Zap,
  Package,
  Sparkles,
  CreditCard,
  Tag,
  Globe,
  File,
  Layers,
  Filter,
  DollarSign,
  TrendingUp,
  AlertCircle,
  Clock,
  CheckCircle,
  Star,
  Gift,
  Truck,
  FileBarChart,
  ShoppingBag,
  Archive,
  UserPlus,
  CreditCard as Card,
  Percent,
  Award,
  Briefcase,
  Cpu
} from 'lucide-react';

// Données de recherche globales - Structure correspondant à une base de données MySQL d'e-commerce
const SEARCH_DATA = [
  // Pages principales
  { id: 1, type: 'page', title: 'Tableau de bord', path: '/admin', icon: Home, category: 'Navigation', table: 'dashboard' },
  { id: 2, type: 'page', title: 'Commandes', path: '/admin/orders', icon: ShoppingCart, category: 'Ventes', table: 'orders' },
  { id: 3, type: 'page', title: 'Produits', path: '/admin/products', icon: Package, category: 'Catalogue', table: 'products' },
  { id: 4, type: 'page', title: 'Catégories', path: '/admin/categories', icon: Tag, category: 'Catalogue', table: 'categories' },
  { id: 5, type: 'page', title: 'Clients', path: '/admin/customers', icon: Users, category: 'Gestion', table: 'customers' },
  { id: 6, type: 'page', title: 'Analytique', path: '/admin/analytics', icon: BarChart, category: 'Rapports', table: 'analytics' },
  { id: 7, type: 'page', title: 'Messages', path: '/admin/messages', icon: MessageSquare, category: 'Communication', table: 'messages' },
  { id: 8, type: 'page', title: 'Paramètres', path: '/admin/settings', icon: Settings, category: 'Configuration', table: 'settings' },

  // Pages secondaires
  { id: 9, type: 'page', title: 'Rapports', path: '/admin/reports', icon: FileBarChart, category: 'Rapports', table: 'reports' },
  { id: 10, type: 'page', title: 'Promotions', path: '/admin/promotions', icon: Percent, category: 'Marketing', table: 'promotions' },
  { id: 11, type: 'page', title: 'Inventaire', path: '/admin/inventory', icon: Archive, category: 'Catalogue', table: 'inventory' },
