        priority: 'low',
        table: 'system'
      },
    ];
    setNotifications(mockNotifications);
    setUnreadCount(mockNotifications.filter(n => !n.read).length);
  }, []);

  // Gérer les clics en dehors des menus
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (notificationsRef.current && !notificationsRef.current.contains(event.target)) {
        setShowNotifications(false);
      }
      if (userMenuRef.current && !userMenuRef.current.contains(event.target)) {
        setShowUserMenu(false);
      }
      if (searchRef.current && !searchRef.current.contains(event.target) && 
          !event.target.closest('form') && 
          !event.target.closest('button[aria-label="Rechercher"]')) {
        setIsSearchFocused(false);
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Recherche avec données MySQL
  useEffect(() => {
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase().trim();

      // Recherche dans toutes les colonnes pertinentes
      const results = SEARCH_DATA.filter(item => {
        const searchableText = `
          ${item.title} 
          ${item.category} 
          ${item.details || ''} 
          ${item.type}
          ${item.table || ''}
          ${item.status || ''}
          ${item.stock || ''}
        `.toLowerCase();

        // Recherche par mots-clés
        const keywords = query.split(' ').filter(k => k.length > 2);
        const matches = keywords.some(keyword => 
          searchableText.includes(keyword) ||
          item.title.toLowerCase().includes(keyword)
        );

        return matches || searchableText.includes(query);
      });

      // Trier par pertinence (titres exacts d'abord, puis par type)
      const sortedResults = results.sort((a, b) => {
        const aExactMatch = a.title.toLowerCase() === query;
        const bExactMatch = b.title.toLowerCase() === query;
        if (aExactMatch && !bExactMatch) return -1;
        if (!aExactMatch && bExactMatch) return 1;

        const aStartsWith = a.title.toLowerCase().startsWith(query);
        const bStartsWith = b.title.toLowerCase().startsWith(query);
        if (aStartsWith && !bStartsWith) return -1;
        if (!aStartsWith && bStartsWith) return 1;

        // Priorité des types: page > order > product > customer > etc.
        const typePriority = {
          'page': 1,
          'order': 2,
          'product': 3,
          'customer': 4,
          'category': 5,
          'stat': 6,
          'setting': 7,
          'action': 8,
          'table': 9
        };

        return (typePriority[a.type] || 10) - (typePriority[b.type] || 10);
      });

      setSearchResults(sortedResults.slice(0, 15)); // Limiter à 15 résultats
    } else {
      setSearchResults([]);
    }
  }, [searchQuery]);

  // Marquer tout comme lu
  const markAllAsRead = useCallback(() => {
    setNotifications(prev => prev.map(n => ({ ...n, read: true })));
    setUnreadCount(0);
    setShowNotifications(false);
  }, []);

  // Gérer la recherche
  const handleSearch = useCallback((e) => {
    e.preventDefault();
    if (searchQuery.trim() && searchResults.length > 0) {
      try {
        navigate(searchResults[0].path);
        setSearchQuery('');
        setShowSearch(false);
        setIsSearchFocused(false);
      } catch (error) {
        console.error('Navigation error:', error);
        window.location.href = searchResults[0].path;
      }
    }
  }, [searchQuery, searchResults, navigate]);

  // Navigation sécurisée
  const handleNavigation = useCallback((path) => {
    try {
      navigate(path);
    } catch (error) {
      console.error('Navigation error:', error);
      window.location.href = path;
    }
  }, [navigate]);

  // Raccourcis clavier
  useEffect(() => {
    const handleKeyDown = (e) => {
      // Ctrl + K ou / pour la recherche
      if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        setShowSearch(true);
        setTimeout(() => {
          searchInputRef.current?.focus();
        }, 100);
      }

      // Échap pour fermer les menus
      if (e.key === 'Escape') {
        setShowNotifications(false);
        setShowUserMenu(false);
        setShowSearch(false);
        setIsSearchFocused(false);
      }

      // Flèches pour naviguer dans les résultats
      if ((e.key === 'ArrowDown' || e.key === 'ArrowUp') && isSearchFocused && searchResults.length > 0) {
        e.preventDefault();
        // Implémentation simplifiée de la navigation par clavier
        const results = document.querySelectorAll('[data-search-result]');
        if (results.length > 0) {
          const currentIndex = Array.from(results).findIndex(el => el === document.activeElement);
          let nextIndex;

          if (e.key === 'ArrowDown') {
            nextIndex = currentIndex < results.length - 1 ? currentIndex + 1 : 0;
          } else {
            nextIndex = currentIndex > 0 ? currentIndex - 1 : results.length - 1;
          }

          results[nextIndex]?.focus();
        }
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isSearchFocused, searchResults.length]);

  // Focus sur l'input de recherche quand showSearch change
  useEffect(() => {
    if (showSearch) {
      setTimeout(() => {
        searchInputRef.current?.focus();
      }, 100);
    }
  }, [showSearch]);

  const getPageTitle = () => {
    const path = location.pathname;
    const pageTitles = {
      '/admin': 'Tableau de bord',
      '/admin/users': 'Gestion des utilisateurs',
      '/admin/products': 'Gestion des produits',
      '/admin/orders': 'Commandes',
      '/admin/analytics': 'Analytique',
      '/admin/messages': 'Messages',
      '/admin/settings': 'Paramètres',
      '/admin/reports': 'Rapports',
      '/admin/calendar': 'Calendrier',
      '/admin/notifications': 'Notifications',
      '/admin/system': 'Système',
      '/admin/database': 'Base de données',
      '/admin/backup': 'Sauvegarde',
      '/admin/profile': 'Mon profil',
      '/admin/help': 'Aide & Support',
      '/admin/customers': 'Clients',
      '/admin/categories': 'Catégories',
      '/admin/inventory': 'Inventaire',
      '/admin/shipping': 'Expédition',
      '/admin/payments': 'Paiements',
      '/admin/promotions': 'Promotions',
    };
    return pageTitles[path] || 'Tableau de bord';
  };

  const getBreadcrumbs = () => {
    const path = location.pathname;
    const segments = path.split('/').filter(s => s);

    if (segments.length === 0) return [{ label: 'Tableau de bord', path: '/' }];

    const breadcrumbMap = {
      'admin': { label: 'Tableau de bord', path: '/admin', icon: Home },
      'users': { label: 'Utilisateurs', path: '/admin/users', icon: Users },
      'products': { label: 'Produits', path: '/admin/products', icon: Package },
      'orders': { label: 'Commandes', path: '/admin/orders', icon: ShoppingCart },
      'analytics': { label: 'Analytique', path: '/admin/analytics', icon: BarChart },
      'messages': { label: 'Messages', path: '/admin/messages', icon: MessageSquare },
      'settings': { label: 'Paramètres', path: '/admin/settings', icon: Settings },
      'reports': { label: 'Rapports', path: '/admin/reports', icon: FileBarChart },
      'calendar': { label: 'Calendrier', path: '/admin/calendar', icon: Calendar },
      'notifications': { label: 'Notifications', path: '/admin/notifications', icon: Bell },
      'system': { label: 'Système', path: '/admin/system', icon: Shield },
      'database': { label: 'Base de données', path: '/admin/database', icon: Database },
      'backup': { label: 'Sauvegarde', path: '/admin/backup', icon: Database },
      'profile': { label: 'Profil', path: '/admin/profile', icon: User },
      'help': { label: 'Aide', path: '/admin/help', icon: HelpCircle },
      'customers': { label: 'Clients', path: '/admin/customers', icon: Users },
      'categories': { label: 'Catégories', path: '/admin/categories', icon: Tag },
      'inventory': { label: 'Inventaire', path: '/admin/inventory', icon: Archive },
      'shipping': { label: 'Expédition', path: '/admin/shipping', icon: Truck },
      'payments': { label: 'Paiements', path: '/admin/payments', icon: CreditCard },
      'promotions': { label: 'Promotions', path: '/admin/promotions', icon: Percent },
    };

    const breadcrumbs = [];
    let currentPath = '';

    segments.forEach(segment => {
      currentPath += `/${segment}`;
      const crumb = breadcrumbMap[segment] || { 
        label: segment.charAt(0).toUpperCase() + segment.slice(1).replace(/-/g, ' '), 
        path: currentPath 
      };
      breadcrumbs.push(crumb);
    });

    return breadcrumbs;
  };

  const pageTitle = getPageTitle();
  const breadcrumbs = getBreadcrumbs();

  // Gestion de la déconnexion
  const handleLogout = useCallback(() => {
    try {
      localStorage.removeItem('authToken');
      localStorage.removeItem('userData');
