  const getStatusColor = (status) => {
    switch(status) {
      case 'processing': return 'bg-blue-500/10 text-blue-600 dark:text-blue-400';
      case 'shipped': return 'bg-purple-500/10 text-purple-600 dark:text-purple-400';
      case 'delivered': return 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400';
      case 'pending': return 'bg-amber-500/10 text-amber-600 dark:text-amber-400';
      case 'cancelled': return 'bg-red-500/10 text-red-600 dark:text-red-400';
      default: return 'bg-neutral-500/10 text-neutral-600 dark:text-neutral-400';
    }
  };

  return (
    <header className="sticky top-0 z-50 bg-white/80 dark:bg-neutral-900/80 backdrop-blur-xl 
      border-b border-neutral-200/50 dark:border-neutral-800/50 transition-all duration-500">

      {/* Barre supérieure */}
      <div className="px-4 sm:px-6 lg:px-8 py-4">
        <div className="flex items-center justify-between">

          {/* Partie gauche */}
