                            <div className="flex-1 min-w-0">
                              <div className="flex items-center justify-between mb-1">
                                <p className="font-medium text-neutral-900 dark:text-white truncate">
                                  {result.title}
                                </p>
                                {result.status && StatusIcon && (
                                  <StatusIcon className={`h-4 w-4 ${
                                    result.status === 'delivered' ? 'text-emerald-500' :
                                    result.status === 'shipped' ? 'text-purple-500' :
                                    result.status === 'processing' ? 'text-blue-500' :
                                    result.status === 'pending' ? 'text-amber-500' :
                                    'text-red-500'
                                  }`} />
                                )}
                              </div>
                              <p className="text-xs text-neutral-500 truncate">
                                {result.details || `Table: ${result.table}`}
                              </p>
                            </div>
                            <ChevronRight className="h-4 w-4 text-neutral-400 flex-shrink-0" />
                          </button>
                        );
                      })}
                    </div>
                  </div>
                ))}
              </div>
            ) : searchQuery.trim() ? (
              <div className="text-center py-12">
                <div className="h-16 w-16 mx-auto mb-4 rounded-full bg-neutral-100 
                  dark:bg-neutral-800 flex items-center justify-center">
                  <Database className="h-8 w-8 text-neutral-400" />
                </div>
                <p className="text-neutral-500 dark:text-neutral-400 font-medium">
                  Aucun résultat trouvé dans MySQL
                </p>
                <p className="text-sm text-neutral-400 mt-1">
                  Essayez avec d'autres termes ou recherchez dans différentes tables
                </p>

                <div className="mt-6 grid grid-cols-2 gap-2 max-w-md mx-auto">
                  <button
                    onClick={() => {
                      setSearchQuery('orders');
                      searchInputRef.current?.focus();
                    }}
                    className="p-3 rounded-lg bg-neutral-100 dark:bg-neutral-700 hover:bg-neutral-200 
                      dark:hover:bg-neutral-600 transition-colors text-left"
                    type="button"
                  >
                    <ShoppingCart className="h-4 w-4 inline mr-2 text-emerald-600" />
                    <span className="text-sm">Table: orders</span>
                  </button>
                  <button
                    onClick={() => {
                      setSearchQuery('products');
                      searchInputRef.current?.focus();
                    }}
                    className="p-3 rounded-lg bg-neutral-100 dark:bg-neutral-700 hover:bg-neutral-200 
                      dark:hover:bg-neutral-600 transition-colors text-left"
                    type="button"
                  >
                    <Package className="h-4 w-4 inline mr-2 text-blue-600" />
                    <span className="text-sm">Table: products</span>
                  </button>
                  <button
                    onClick={() => {
                      setSearchQuery('customers');
                      searchInputRef.current?.focus();
                    }}
                    className="p-3 rounded-lg bg-neutral-100 dark:bg-neutral-700 hover:bg-neutral-200 
                      dark:hover:bg-neutral-600 transition-colors text-left"
                    type="button"
                  >
                    <Users className="h-4 w-4 inline mr-2 text-purple-600" />
                    <span className="text-sm">Table: customers</span>
                  </button>
                  <button
                    onClick={() => {
                      setSearchQuery('categories');
                      searchInputRef.current?.focus();
                    }}
                    className="p-3 rounded-lg bg-neutral-100 dark:bg-neutral-700 hover:bg-neutral-200 
                      dark:hover:bg-neutral-600 transition-colors text-left"
                    type="button"
                  >
                    <Tag className="h-4 w-4 inline mr-2 text-amber-600" />
                    <span className="text-sm">Table: categories</span>
                  </button>
                </div>
              </div>
            ) : (
              <div className="text-center py-12">
                <div className="h-16 w-16 mx-auto mb-4 rounded-full bg-gradient-to-r from-primary-500/20 
                  to-secondary-500/20 flex items-center justify-center">
                  <Database className="h-8 w-8 text-primary-600" />
                </div>
                <p className="text-neutral-500 dark:text-neutral-400 font-medium">
                  Recherche MySQL
                </p>
                <p className="text-sm text-neutral-400 mt-1">
                  Commandes, produits, clients, catégories, paiements...
                </p>

                <div className="mt-6">
                  <p className="text-sm font-medium text-neutral-600 dark:text-neutral-400 mb-3">
                    Tables principales:
                  </p>
                  <div className="grid grid-cols-2 gap-2 max-w-md mx-auto">
                    <div className="p-3 rounded-lg bg-blue-500/10 text-blue-600 dark:text-blue-400">
                      <Database className="h-4 w-4 inline mr-2" />
                      <span className="text-sm">orders (12,456)</span>
                    </div>
                    <div className="p-3 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400">
                      <Database className="h-4 w-4 inline mr-2" />
                      <span className="text-sm">customers (8,923)</span>
                    </div>
                    <div className="p-3 rounded-lg bg-purple-500/10 text-purple-600 dark:text-purple-400">
                      <Database className="h-4 w-4 inline mr-2" />
                      <span className="text-sm">products (456)</span>
                    </div>
                    <div className="p-3 rounded-lg bg-amber-500/10 text-amber-600 dark:text-amber-400">
                      <Database className="h-4 w-4 inline mr-2" />
                      <span className="text-sm">payments (12,456)</span>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      )}
    </header>
  );
};

export default TopBar;
